{
  "id": "real-options-investment-timing-fin",
  "name": "Real Options Investment Model",
  "description": "Model of investment timing under uncertainty using real options theory. Source: Dixit & Pindyck (1994), Investment under Uncertainty.",
  "stocks": [
    {
      "id": "s1",
      "name": "Asset_Value",
      "initial_value": 100,
      "equation": "",
      "position": {
        "x": 200,
        "y": 200
      }
    },
    {
      "id": "s2",
      "name": "Option_Value",
      "initial_value": 50,
      "equation": "",
      "position": {
        "x": 400,
        "y": 200
      }
    },
    {
      "id": "s3",
      "name": "Invested",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 300,
        "y": 350
      }
    }
  ],
  "flows": [
    {
      "id": "f1",
      "name": "Value_Drift",
      "equation": "mu * Asset_Value + sigma * Asset_Value * Noise",
      "from_stock": null,
      "to_stock": "s1",
      "position": {
        "x": 100,
        "y": 200
      }
    },
    {
      "id": "f2",
      "name": "Option_Change",
      "equation": "MAX(0, Asset_Value - Investment_Cost) - Option_Value",
      "from_stock": null,
      "to_stock": "s2",
      "position": {
        "x": 500,
        "y": 200
      }
    },
    {
      "id": "f3",
      "name": "Investment_Decision",
      "equation": "IF(Asset_Value > Trigger_Value AND Invested < 1, 1, 0)",
      "from_stock": null,
      "to_stock": "s3",
      "position": {
        "x": 200,
        "y": 350
      }
    }
  ],
  "variables": [
    {
      "id": "v1",
      "name": "mu",
      "equation": "0.05",
      "position": {
        "x": 150,
        "y": 50
      }
    },
    {
      "id": "v2",
      "name": "sigma",
      "equation": "0.2",
      "position": {
        "x": 250,
        "y": 50
      }
    },
    {
      "id": "v3",
      "name": "r",
      "equation": "0.05",
      "position": {
        "x": 350,
        "y": 50
      }
    },
    {
      "id": "v4",
      "name": "Investment_Cost",
      "equation": "80",
      "position": {
        "x": 450,
        "y": 50
      }
    },
    {
      "id": "v5",
      "name": "beta",
      "equation": "(0.5 - mu / sigma^2) + ((mu / sigma^2 - 0.5)^2 + 2 * r / sigma^2)^0.5",
      "position": {
        "x": 200,
        "y": 100
      }
    },
    {
      "id": "v6",
      "name": "Trigger_Value",
      "equation": "Investment_Cost * beta / (beta - 1)",
      "position": {
        "x": 400,
        "y": 100
      }
    },
    {
      "id": "v7",
      "name": "Noise",
      "equation": "(SIN(TIME * 17.3) + COS(TIME * 23.1)) * 0.05",
      "position": {
        "x": 150,
        "y": 450
      }
    }
  ],
  "connectors": [
    {
      "id": "c1",
      "from_element": "Asset_Value",
      "to_element": "Investment_Decision"
    }
  ],
  "time_settings": {
    "start": 0,
    "end": 50,
    "dt": 0.25
  },
  "created_at": "2026-01-15T14:41:20.230321+00:00",
  "updated_at": "2026-01-15T14:41:20.230325+00:00",
  "source": "https://press.princeton.edu/books/hardcover/9780691034102/investment-under-uncertainty",
  "reference": "Dixit, A.K. & Pindyck, R.S. (1994). Investment under Uncertainty. Princeton UP."
}

{
  "id": "antibiotic-resistance-evolution-extended-hea",
  "name": "Antibiotic Resistance Evolution Extended Model",
  "description": "Illustrative Antibiotic Resistance Evolution Extended Model. Source reconciliation 2026-10-20: The corrected Laxminarayan et al. citation is a commission review, not the source of these ODEs. All bacterial stocks and effectiveness start at zero, giving 0/0 in Effectiveness_Decay. Drug_Approval transfers an amount of pipeline drugs directly to dimensionless effectiveness; no unit conversion or source for coefficients/initial values is established. No guessed bacterial seed or effectiveness was inserted. Scientific calibration and applicability remain unverified.",
  "stocks": [
    {
      "id": "stock-susceptible-bacteria",
      "name": "Susceptible_Bacteria",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 150,
        "y": 150
      }
    },
    {
      "id": "stock-resistant-bacteria",
      "name": "Resistant_Bacteria",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 350,
        "y": 150
      }
    },
    {
      "id": "stock-multi-resistant",
      "name": "Multi_Resistant_Bacteria",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 550,
        "y": 150
      }
    },
    {
      "id": "stock-antibiotic-effectiveness",
      "name": "Antibiotic_Effectiveness",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 250,
        "y": 300
      }
    },
    {
      "id": "stock-new-drug-pipeline",
      "name": "New_Drug_Pipeline",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 450,
        "y": 300
      }
    }
  ],
  "flows": [
    {
      "id": "flow-susceptible-growth",
      "name": "Susceptible_Growth",
      "equation": "Susceptible_Bacteria * Growth_Rate * (1 - Total_Bacteria / Carrying_Capacity)",
      "from_stock": null,
      "to_stock": "stock-susceptible-bacteria",
      "position": {
        "x": 75,
        "y": 150
      }
    },
    {
      "id": "flow-mutation-single",
      "name": "Single_Mutation",
      "equation": "Susceptible_Bacteria * Mutation_Rate * Antibiotic_Pressure",
      "from_stock": "stock-susceptible-bacteria",
      "to_stock": "stock-resistant-bacteria",
      "position": {
        "x": 250,
        "y": 150
      }
    },
    {
      "id": "flow-mutation-multi",
      "name": "Multi_Mutation",
      "equation": "Resistant_Bacteria * Mutation_Rate * Antibiotic_Pressure * 0.1",
      "from_stock": "stock-resistant-bacteria",
      "to_stock": "stock-multi-resistant",
      "position": {
        "x": 450,
        "y": 150
      }
    },
    {
      "id": "flow-antibiotic-kill-susceptible",
      "name": "Kill_Susceptible",
      "equation": "Susceptible_Bacteria * Antibiotic_Effectiveness * Treatment_Rate",
      "from_stock": "stock-susceptible-bacteria",
      "to_stock": null,
      "position": {
        "x": 150,
        "y": 220
      }
    },
    {
      "id": "flow-antibiotic-kill-resistant",
      "name": "Kill_Resistant",
      "equation": "Resistant_Bacteria * Antibiotic_Effectiveness * Treatment_Rate * Resistance_Reduction",
      "from_stock": "stock-resistant-bacteria",
      "to_stock": null,
      "position": {
        "x": 350,
        "y": 220
      }
    },
    {
      "id": "flow-effectiveness-decay",
      "name": "Effectiveness_Decay",
      "equation": "Antibiotic_Effectiveness * (Resistant_Bacteria + Multi_Resistant_Bacteria) / Total_Bacteria * Decay_Rate",
      "from_stock": "stock-antibiotic-effectiveness",
      "to_stock": null,
      "position": {
        "x": 250,
        "y": 370
      }
    },
    {
      "id": "flow-new-drug-development",
      "name": "New_Drug_Development",
      "equation": "RD_Investment / Development_Cost",
      "from_stock": null,
      "to_stock": "stock-new-drug-pipeline",
      "position": {
        "x": 350,
        "y": 300
      }
    },
    {
      "id": "flow-drug-approval",
      "name": "Drug_Approval",
      "equation": "New_Drug_Pipeline / Approval_Time",
      "from_stock": "stock-new-drug-pipeline",
      "to_stock": "stock-antibiotic-effectiveness",
      "position": {
        "x": 350,
        "y": 350
      }
    }
  ],
  "variables": [
    {
      "id": "var-growth-rate",
      "name": "Growth_Rate",
      "equation": "0.5",
      "position": {
        "x": 100,
        "y": 80
      }
    },
    {
      "id": "var-carrying-capacity",
      "name": "Carrying_Capacity",
      "equation": "1000000",
      "position": {
        "x": 220,
        "y": 80
      }
    },
    {
      "id": "var-total-bacteria",
      "name": "Total_Bacteria",
      "equation": "Susceptible_Bacteria + Resistant_Bacteria + Multi_Resistant_Bacteria",
      "position": {
        "x": 380,
        "y": 80
      }
    },
    {
      "id": "var-mutation-rate",
      "name": "Mutation_Rate",
      "equation": "0.0001",
      "position": {
        "x": 540,
        "y": 80
      }
    },
    {
      "id": "var-antibiotic-pressure",
      "name": "Antibiotic_Pressure",
      "equation": "0.5",
      "position": {
        "x": 660,
        "y": 80
      }
    },
    {
      "id": "var-treatment-rate",
      "name": "Treatment_Rate",
      "equation": "0.3",
      "position": {
        "x": 100,
        "y": 400
      }
    },
    {
      "id": "var-resistance-reduction",
      "name": "Resistance_Reduction",
      "equation": "0.3",
      "position": {
        "x": 220,
        "y": 400
      }
    },
    {
      "id": "var-decay-rate",
      "name": "Decay_Rate",
      "equation": "0.01",
      "position": {
        "x": 340,
        "y": 400
      }
    },
    {
      "id": "var-rd-investment",
      "name": "RD_Investment",
      "equation": "10",
      "position": {
        "x": 460,
        "y": 400
      }
    },
    {
      "id": "var-development-cost",
      "name": "Development_Cost",
      "equation": "1000",
      "position": {
        "x": 580,
        "y": 400
      }
    },
    {
      "id": "var-approval-time",
      "name": "Approval_Time",
      "equation": "10",
      "position": {
        "x": 700,
        "y": 400
      }
    }
  ],
  "connectors": [],
  "time_settings": {
    "start": 0,
    "end": 100,
    "dt": 0.25
  },
  "created_at": "2026-01-12T01:15:55.420135+00:00",
  "updated_at": "2026-01-12T01:15:55.420145+00:00",
  "source": "https://doi.org/10.1016/S1473-3099(13)70318-9",
  "reference": "Laxminarayan R, et al. Antibiotic resistance—the need for global solutions. Lancet Infectious Diseases. 2013;13(12):1057-1098. General context only; not a source of the implemented equations."
}

{
  "id": "burnout-recovery-cycle-hea",
  "name": "Burnout and Recovery Cycle Model",
  "description": "Illustrative Burnout and Recovery Cycle Model. Source reconciliation 2026-10-20: Maslach et al. defines exhaustion, cynicism and inefficacy; the energy/stress/burnout stock system is an illustrative construction, not a reproduced or calibrated burnout measure. At the initial state energy restoration is 2 and drain is 42 per model time; energy derivative is -40. No source justifies the scales, time unit, boundary behavior or coefficients, and adding arbitrary clipping would not validate them. Scientific calibration and applicability remain unverified.",
  "stocks": [
    {
      "id": "stock-energy",
      "name": "Personal_Energy",
      "initial_value": 80,
      "equation": "",
      "position": {
        "x": 200,
        "y": 200
      }
    },
    {
      "id": "stock-stress",
      "name": "Accumulated_Stress",
      "initial_value": 20,
      "equation": "",
      "position": {
        "x": 400,
        "y": 200
      }
    },
    {
      "id": "stock-burned",
      "name": "Burnout_Level",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 300,
        "y": 350
      }
    }
  ],
  "flows": [
    {
      "id": "flow-restore",
      "name": "Energy_Restoration",
      "equation": "(Max_Energy - Personal_Energy) * Recovery_Rate * (1 - Burnout_Level / 100)",
      "from_stock": null,
      "to_stock": "stock-energy",
      "position": {
        "x": 200,
        "y": 100
      }
    },
    {
      "id": "flow-drain",
      "name": "Energy_Drain",
      "equation": "Workload * Stress_Sensitivity * (1 + Accumulated_Stress / 50)",
      "from_stock": "stock-energy",
      "to_stock": null,
      "position": {
        "x": 200,
        "y": 300
      }
    },
    {
      "id": "flow-stress-add",
      "name": "Stress_Accumulation",
      "equation": "Workload * (1 - Personal_Energy / 100)",
      "from_stock": null,
      "to_stock": "stock-stress",
      "position": {
        "x": 400,
        "y": 100
      }
    },
    {
      "id": "flow-stress-rel",
      "name": "Stress_Release",
      "equation": "Accumulated_Stress * Coping_Rate",
      "from_stock": "stock-stress",
      "to_stock": null,
      "position": {
        "x": 400,
        "y": 300
      }
    },
    {
      "id": "flow-burnout-on",
      "name": "Burnout_Onset",
      "equation": "Accumulated_Stress * (1 - Personal_Energy / 100) * 0.05",
      "from_stock": null,
      "to_stock": "stock-burned",
      "position": {
        "x": 200,
        "y": 350
      }
    },
    {
      "id": "flow-burnout-rec",
      "name": "Burnout_Recovery",
      "equation": "Burnout_Level * Recovery_Support * 0.02",
      "from_stock": "stock-burned",
      "to_stock": null,
      "position": {
        "x": 400,
        "y": 350
      }
    }
  ],
  "variables": [
    {
      "id": "var-max",
      "name": "Max_Energy",
      "equation": "100",
      "position": {
        "x": 100,
        "y": 50
      }
    },
    {
      "id": "var-recovery",
      "name": "Recovery_Rate",
      "equation": "0.1",
      "position": {
        "x": 200,
        "y": 50
      }
    },
    {
      "id": "var-workload",
      "name": "Workload",
      "equation": "60",
      "position": {
        "x": 300,
        "y": 50
      }
    },
    {
      "id": "var-sens",
      "name": "Stress_Sensitivity",
      "equation": "0.5",
      "position": {
        "x": 100,
        "y": 250
      }
    },
    {
      "id": "var-coping",
      "name": "Coping_Rate",
      "equation": "0.15",
      "position": {
        "x": 500,
        "y": 250
      }
    },
    {
      "id": "var-support",
      "name": "Recovery_Support",
      "equation": "1.0",
      "position": {
        "x": 500,
        "y": 400
      }
    }
  ],
  "connectors": [
    {
      "id": "c1",
      "from_element": "Max_Energy",
      "to_element": "Energy_Restoration"
    },
    {
      "id": "c2",
      "from_element": "Personal_Energy",
      "to_element": "Energy_Restoration"
    },
    {
      "id": "c3",
      "from_element": "Recovery_Rate",
      "to_element": "Energy_Restoration"
    },
    {
      "id": "c4",
      "from_element": "Burnout_Level",
      "to_element": "Energy_Restoration"
    },
    {
      "id": "c5",
      "from_element": "Workload",
      "to_element": "Energy_Drain"
    },
    {
      "id": "c6",
      "from_element": "Stress_Sensitivity",
      "to_element": "Energy_Drain"
    },
    {
      "id": "c7",
      "from_element": "Accumulated_Stress",
      "to_element": "Energy_Drain"
    },
    {
      "id": "c8",
      "from_element": "Workload",
      "to_element": "Stress_Accumulation"
    },
    {
      "id": "c9",
      "from_element": "Personal_Energy",
      "to_element": "Stress_Accumulation"
    },
    {
      "id": "c10",
      "from_element": "Accumulated_Stress",
      "to_element": "Stress_Release"
    },
    {
      "id": "c11",
      "from_element": "Coping_Rate",
      "to_element": "Stress_Release"
    },
    {
      "id": "c12",
      "from_element": "Accumulated_Stress",
      "to_element": "Burnout_Onset"
    },
    {
      "id": "c13",
      "from_element": "Personal_Energy",
      "to_element": "Burnout_Onset"
    },
    {
      "id": "c14",
      "from_element": "Burnout_Level",
      "to_element": "Burnout_Recovery"
    },
    {
      "id": "c15",
      "from_element": "Recovery_Support",
      "to_element": "Burnout_Recovery"
    }
  ],
  "time_settings": {
    "start": 0,
    "end": 52,
    "dt": 1
  },
  "created_at": "2026-01-12T11:49:16.387836+00:00",
  "updated_at": "2026-01-12T11:49:16.387840+00:00",
  "source": "https://doi.org/10.1146/annurev.psych.52.1.397",
  "reference": "Maslach C, Schaufeli WB, Leiter MP. Job Burnout. Annual Review of Psychology. 2001;52:397-422."
}

{
