    {
      "id": "var-heat-input",
      "name": "Heat_Input",
      "equation": "10",
      "position": {
        "x": 50,
        "y": 350
      }
    },
    {
      "id": "var-heat-loss",
      "name": "Heat_Loss",
      "equation": "Top_Temperature * 0.1",
      "position": {
        "x": 50,
        "y": 50
      }
    }
  ],
